        if (this.state !== 'STREAMING') return;
        // Memory-safe merging without reallocation bloat
        const newBuffer = new ArrayBuffer(this.buffer.byteLength + chunk.byteLength);
        const view = new Uint8Array(newBuffer);
        view.set(new Uint8Array(this.buffer), 0);
        view.set(chunk, this.buffer.byteLength);
        this.buffer = newBuffer;
